import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import sailpoint.object.Attributes;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AttributeRequest;

if (plan == null || plan.getAccountRequests() == null) return;

for (Object o : plan.getAccountRequests()) {
    AccountRequest acct = (AccountRequest) o;
    List attrReqs = acct.getAttributeRequests();
    if (attrReqs == null) continue;

    List adds = new ArrayList();
    List removes = new ArrayList();
    Iterator it = attrReqs.iterator();
    while (it.hasNext()) {
        AttributeRequest req = (AttributeRequest) it.next();
        if (!"groups".equals(req.getName())) continue;

        Object value = req.getValue();
        List values = new ArrayList();
        if (value instanceof List) values.addAll((List) value);
        else if (value != null) values.add(value);

        if (ProvisioningPlan.Operation.Remove.equals(req.getOperation())) {
            removes.addAll(values);
        } else {
            adds.addAll(values);
        }
        it.remove();
    }

    if (adds.isEmpty() && removes.isEmpty()) continue;
    Attributes args = acct.getArguments();
    if (args == null) {
        args = new Attributes();
        acct.setArguments(args);
    }
    args.put("hrGroupsAdd", adds);
    args.put("hrGroupsRemove", removes);
    log.debug("LDAP ApacheDS: moved group changes for " + acct.getNativeIdentity()
              + " add=" + adds + " remove=" + removes);
}
